/* Başlıklar */
h2 {
    font-size: 20px;
    margin-bottom: 10px;
    color: #0b3c5d;
}

/* Metinler */
p {
    font-size: 14px;
    line-height: 1.6;
    color: #333;
    margin-bottom: 12px;
}

/* Ayırıcı */
hr {
    border: none;
    border-top: 1px solid #cfe8f6;
    margin: 25px 0;
}

/* Tablo kapsayıcı */
.product-table-container {
    width: 100%;
    overflow-x: auto;
    margin-top: 15px;
}

/* Tablo */
.product-table-container table {
    width: 100%;
    min-width: 600px;
    border-collapse: collapse;
    background-color: #ffffff;
    font-size: 14px;
    border-radius: 8px;
    overflow: hidden;
}

/* Tablo başlıkları */
.product-table-container thead th {
    background: linear-gradient(90deg, #1e88e5, #64b5f6);
    color: #ffffff;
    font-weight: 700;
    text-align: left;
    padding: 12px 14px;
    border-bottom: 2px solid #1e88e5;
}

/* Tablo hücreleri */
.product-table-container tbody td {
    padding: 12px 14px;
    border-bottom: 1px solid #d6eaf8;
    vertical-align: top;
}

/* Sol sütun */
.product-table-container tbody td:first-child {
    width: 30%;
    font-weight: 600;
    background-color: #eef6fc;
    color: #0b3c5d;
}

/* Zebra satırlar */
.product-table-container tbody tr:nth-child(even) td {
    background-color: #f8fbfe;
}

/* Hover efekti */
.product-table-container tbody tr:hover td {
    background-color: #e3f2fd;
    transition: background-color 0.2s ease;
}

/* Liste */
ul {
    padding-left: 20px;
    font-size: 14px;
}


